export interface MessageSender {
  agentID: UUID;
  title: string;
}

/**
 * One conversation in messages/conversations (#4343): the connector it is on (server, its name in
 * mcp.json, and a folder that reaches it, which messages/read takes) and the conversation as the
 * connector's list_conversations gave it. replyAs (#4345) is who a reply from the page goes as, in
 * words (the Slack bot, the WhatsApp number): present only when the connector has the contract's
 * reply tool, so a client shows a reply field only then.
 */
export interface MessagesConversation {
  server: string;
  folder: string;
  conversation: MessagingConversation;
  replyAs?: string;
}

/**
 * messages/conversations (#4343): a page of the conversations of every connector in the Messaging
 * slot that follows the messaging contract, merged by lastActivity, the newest first. cursor is the
 * next page, absent at the end. errors says a connector that failed or did not answer in time, and
 * the conversations of the others still come.
 */
export interface MessagesConversations {
  conversations: MessagesConversation[];
  cursor?: string;
  errors?: MessagesError[];
}

/**
 * messages/conversations (#4343): the conversations of every folder's messaging connectors on this
 * machine, or of one folder's. limit is 1 to 100, 20 when not said; cursor is the last page's.
 * unread: only the conversations with unread messages.
 */
export interface MessagesConversationsRequest {
  folder?: string;
  cursor?: string;
  limit?: number;
  unread?: boolean;
}

/**
 * A connector messages/conversations could not read (#4343): its name in mcp.json, a folder that
 * reaches it, and why, in a sentence.
 */
export interface MessagesError {
  server: string;
  folder: string;
  message: string;
}

/**
 * messages/read (#4343): one page of a conversation's messages, newest first, as the connector's
 * read_messages gave it. cursor gives the older page; absent on the last. untrusted is always true:
 * every text is outside content.
 */
export interface MessagesRead {
  server: string;
  folder: string;
  conversation: string;
  messages: MessagingMessage[];
  cursor?: string;
  untrusted: boolean;
}

/**
 * messages/read (#4343): a conversation from messages/conversations, by its server, folder and id.
 * cursor is the last page's; thread: only that thread's messages; limit is 1 to 100, 20 when not
 * said.
 */
export interface MessagesReadRequest {
  server: string;
  folder: string;
  conversation: string;
  cursor?: string;
  thread?: string;
  limit?: number;
}

/** messages/reply (#4345): the message that the connector's reply tool sent. */
export interface MessagesReplied {
  server: string;
  folder: string;
  conversation: string;
  message: MessagingMessage;
}

/**
 * messages/reply (#4345): the person's own reply, from the Messages page, to a conversation from
 * messages/conversations, by its server, folder and id; thread: the thread to answer in (absent:
 * the conversation itself). The connector's reply tool sends it, as the connector's replyAs says.
 */
export interface MessagesReplyRequest {
  server: string;
  folder: string;
  conversation: string;
  thread?: string;
  text: string;
}

/**
 * One conversation in a messaging contract server's list_conversations (#4338,
 * docs/reference/messaging-contract.md): a channel, a space, a direct chat or a mail thread. source
 * is the service (slack, email, googlechat, whatsapp, or the server's own word), the same word as
 * ChannelSender.channel. unread is the service's own count of unread messages; absent when the
 * service does not say. lastActivity is the newest message's time.
 */
export interface MessagingConversation {
  source: string;
  /**
   * The server's id for the conversation, which read_messages and reply take. Opaque to the daemon
   * and the clients.
   */
  id: string;
  title: string;
  kind: MessagingConversationKind;
  unread?: number;
  lastActivity?: string;
  /** The conversation on the service's own site or app. Absent when it has none. */
  link?: URLString;
}

/**
 * channel: a channel or space that many people read. direct: a chat with one person or a small
 * group. thread: a mail thread (References and In-Reply-To).
 */
export type MessagingConversationKind =
  | "channel"
  | "direct"
  | "thread";

/**
 * list_conversations' structuredContent (#4338): the conversations, newest lastActivity first.
 * cursor is absent on the last page. replyAs (#4345): who the server's reply tool sends as, in
 * words (the Slack bot @agents, the WhatsApp number); absent when the server has no reply tool.
 */
export interface MessagingConversations {
  conversations: MessagingConversation[];
  cursor?: string;
  replyAs?: string;
}

/**
 * list_conversations' input (#4338). cursor is a page's cursor from the last answer; limit is at
 * most 100, 20 when left out. unread: only the conversations with unread messages. A server may
 * take more inputs of its own, each optional (the email server's folder).
 */
export interface MessagingListRequest {
  cursor?: string;
  limit?: number;
  unread?: boolean;
}

/**
 * One message in read_messages' structuredContent (#4338). text is outside content: the result says
 * so (untrusted), and a client draws it as Markdown that loads nothing: no HTML, no image from the
 * network, and only http, https and mailto links. thread is the id of the message that starts its
 * thread; absent when it is in no thread. link is the message on the service's own site or app.
 */
export interface MessagingMessage {
  id: string;
  conversation: string;
  sender: ChannelSender;
  time: string;
  text: string;
  thread?: string;
  link?: URLString;
}

/**
 * read_messages' structuredContent (#4338): one page of a conversation's messages, newest first.
 * cursor gives the older page; absent on the last. untrusted is always true: every text is outside
 * content.
 */
export interface MessagingMessages {
  conversation: string;
  messages: MessagingMessage[];
  cursor?: string;
  untrusted: boolean;
}

/**
 * read_messages' input (#4338): a conversation's id from list_conversations, and a page's cursor
 * from the last answer. thread: only that thread's messages. limit is at most 100, 20 when left
 * out. A server may take more inputs of its own, each optional.
 */
export interface MessagingReadRequest {
  conversation: string;
  cursor?: string;
  thread?: string;
  limit?: number;
}

/**
 * reply's input (#4338, #4345): the conversation, the thread to answer in (a message's thread, or
 * the id of the message that starts one; absent: the conversation itself), and the text. Its
 * structuredContent is the sent message, a MessagingMessage.
 */
export interface MessagingReplyRequest {
  conversation: string;
  thread?: string;
  text: string;
}

/**
 * One messaging connector in the Messaging slot (#1787): its name in mcp.json, what it is in words
 * (Slack, Email, Google Chat, or its name), its one real read (a list of its channels, folders or
 * spaces) and the events it declares.
 */
export interface MessagingServer {
  name: string;
  /**
   * What it is, in words: Slack, Email, Google Chat, WhatsApp, Discord, Telegram, Microsoft Teams,
   * or its name.
   */
  word: string;
  state: MessagingServerState;
  /**
   * What the read found: how many channels, folders or spaces, or its first line. Absent when it
   * did not read.
   */
  proof?: ConnectorProof;
  /** failed: why, in a sentence. */
  message?: string;
  /**
   * The events it declares (slack.message, email.received), from its events/list. Absent with none.
   */
  events?: string[];
}

/**
 * notRead: not read yet. read: its one read worked. failed: the read did not work; message says
 * why.
 */
export type MessagingServerState =
  | "notRead"
  | "read"
  | "failed";

export interface MissingFolder {
  branchKept: boolean;
}

/**
 * Fast: the runtime's smallest quick model; Balanced: its usual model; Smart: its most capable
 * model (#2658).
 */
export type ModelLevel =
  | "fast"
  | "balanced"
  | "smart";

/** What a person's move came to. The message is what the window may show. */
