/**
 * Settings ▸ You ▸ Accounts (#3967): one outside account of the person's (gitlab.com, AWS, Slack…).
 * It holds no secret: card and secret are the names of secrets in Settings ▸ You ▸ Secrets, or
 * where one is.
 */
export interface OutsideAccount {
  /** The service, as its address: gitlab.com, aws.amazon.com. */
  service: string;
  /**
   * What it is for and who uses it, in one or two sentences, so an agent can tell it from the other
   * accounts of the same service (#4164). Absent on an account made before it: the clients say No
   * description.
   */
  description?: string;
  /** The address it signs in with. */
  address?: string;
  /** Free, Pro… */
  plan?: string;
  /** What it costs a month, in US dollars. Absent when not known. */
  monthlyCostUsd?: number;
  /** The card it bills, by its name in Settings ▸ You ▸ Secrets. Never the number. */
  card?: string;
  /** Its token or key, by its name in Settings ▸ You ▸ Secrets or where it is. Never the value. */
  secret?: string;
  /** TOTP, passkey, SMS, or absent for none. */
  twoFactor?: string;
  /** The issue that made it: #12 or owner/repo#12. */
  issue?: string;
  /** The date it was made, YYYY-MM-DD. */
  made?: string;
  /**
   * When it was last changed (#4157): the control plane sets it when an account takes another's
   * place, by manage_accounts or a client's Edit… (#4160). made stays. Absent for one never
   * changed.
   */
  edited?: WireDate;
  /**
   * Its newest operation (#4157): a read or change by manage_accounts, or a read of the secret or
   * card it names, as the machine that answers knows it. The control plane does not store it: it
   * keeps the newest the machines said in memory and puts it on user/settings (#4160), and drops
   * one a client sends.
   */
  lastOp?: AccountLastOp;
  /** The date its token expires, YYYY-MM-DD. */
  tokenExpires?: string;
  /** Where the password is, the account's name and the like. Never a secret. */
  notes?: string;
  /** The projects that use it, by name. Absent or empty: all of them. */
  projects?: string[];
  /**
   * Ask before use (#4163): an agent's manage_accounts get of it waits on a person's approval, as a
   * secret's use does (#4015). Absent is on, also for an account an agent adds; false is off, which
   * a person sets, or Always Approve on its request does. Not sealed: kept with the account, and
   * agentsd enforces it.
   */
  askBeforeUse?: boolean;
}

