/**
 * Each person's budget per UTC day and per agent (#998, FR-016): a ceiling over their own
 * CostLimits. Money is US dollars.
 */
export interface PolicyBudgets {
  daily?: number;
  dailyTokens?: number;
  perAgent?: number;
  perAgentTokens?: number;
  /**
   * Runtime ids that may run under a budget though their turns report neither a cost nor tokens.
   */
  allowUnmetered: string[];
  /** An admin's raises, each for one person and one UTC day. */
  raises: BudgetRaise[];
}

/**
 * The levels a layer sets for one connector's tools (#4099). A tool's own level comes before the
 * layer's writes switch.
 */
export interface PolicyConnectorRule {
  /** The level of every tool that writes and that tools does not name. */
  writes?: ConnectorToolLevel;
  /** A level for each tool, by its name. */
  tools?: Record<string, ConnectorToolLevel>;
}

/**
 * policy/effective (#2957): the rules for an agent in folder, or, with no folder, outside any
 * folder layer.
 */
export interface PolicyEffectiveRequest {
  folder?: URLString;
}

/**
 * The variable names a person's own pass-through list may name (#998, FR-011a), * at the end
 * allowed. runtimes names ones for one runtime only (#2957, moved here from
 * runtime-environment.json's own runtimes map).
 */
export interface PolicyEnvironment {
  passThrough: string[];
  runtimes?: Record<string, string[]>;
}

/** policy/folder (#2957): the folder's own layer, from .agents/policy.json. */
export interface PolicyFolderRequest {
  folder: URLString;
}

/**
 * policy/folder's result (#2957, data-model.md "A folder's layer"): the approved copy, and a
 * waiting change when one is pending.
 */
export interface PolicyFolderState {
  rules: PolicyRules;
  pending?: GuardedChange;
  /**
   * Why the file on disk cannot be read as a layer (not JSON, or a value out of range), when that
   * is why a change is pending.
   */
  invalid?: string;
}

/**
 * One folder that sets its own rules, for the Agents ▸ Policy banner (#2957,
 * EffectivePolicy.foldersWithRules).
 */
export interface PolicyFolderWithRules {
  folder: string;
  name: string;
  count: number;
}

/** The ceiling over each folder's helper limits (#998, #64). */
export interface PolicyHelpers {
  mostRunning?: number;
  mostNotArchived?: number;
  mostQueued?: number;
}

/**
 * Which machine signs your layer (#2957, research R4): the Mac's host, or the first machine of
 * yours that saved one, when you have no Mac.
 */
export interface PolicyKeeper {
  host: string;
  name: string;
}

/**
 * policy/get and policy/set (#998): the whole policy with its store tag, for an admin. No policy
 * and no rev when none was ever set. machines is each machine's applied version, by host id.
 */
export interface PolicyKept {
  policy?: OrgPolicy;
  rev?: string;
  machines?: Record<string, number>;
}

/**
 * Which layer sets or decides a rule (#2957, data-model.md "PolicyLayerRef"): the organisation, the
 * person ("You"), or a folder.
 */
export interface PolicyLayerRef {
  kind: "organisation" | "you" | "folder";
  /** The organisation's name, "You", or the folder's name. */
  name: string;
  /** The folder's path, when kind is folder. */
  folder?: string;
}

/**
 * The marketplaces a policy allows (#998), by the ids #687 gives them, and whether an MCP server
 * added by hand is allowed.
 */
export interface PolicyMarketplaces {
  allowed: string[];
  customServers: "allow" | "refuse";
}

/**
 * How many notices a burst allows, and how long to wait after one, before an agent may send another
 * (#2957). Unset means 3 and 10 minutes. Not notices: OrgPolicy.notices already means the
 * Antigravity terms (spec 998).
 */
export interface PolicyNoticeLimits {
  burst?: number;
  waitMinutes?: number;
}

/** The notices a policy decides for every member (#999, FR-008). */
export interface PolicyNotices {
  /**
   * Google's terms notice for Antigravity: show (as absent), accepted (the organisation reviewed
   * them; no notice), refuse (Antigravity is refused).
   */
  antigravityTerms?: "show" | "accepted" | "refuse";
}

/** policy/raise (#998): an admin raises a person's budget for today (UTC). */
export interface PolicyRaiseRequest {
  user: string;
  daily?: number;
  dailyTokens?: number;
  request?: string;
}

/** A way a runtime reaches the model (#999): the person's own sign-in, an org key, or a gateway. */
export type PolicyReach =
  | "signIn"
  | "orgKey"
  | "gateway";

/**
 * The data of a policyRefused error (#998, FR-010): why, the rule, and the words for the client.
 * layer and value name which layer decided and what it allows (#2957, R8): "Acme: at most Approve
 * for me".
 */
export interface PolicyRefusal {
  reason: "policy" | "budget" | "stopAll" | "noPolicy" | "mustJoin" | "update";
  rule?: string;
  words: string;
  until?: WireDate;
  layer?: PolicyLayerRef;
  value?: string;
}

/**
 * policy/refuseMore (#3262), an admin's: refuse an Ask for More. policy/raise with the request's id
 * raises it.
 */
export interface PolicyRefuseMore {
  request: string;
}

/**
 * Money and tokens a layer caps per agent and per UTC day (#2957, data-model.md "PolicyRules").
 * Unset means no limit. Unlike OrgPolicy's PolicyBudgets, no allowUnmetered or raises: only the
 * organisation layer has those (FR-003).
 */
export interface PolicyRuleBudgets {
  perAgent?: Cost;
  daily?: Cost;
  perAgentTokens?: number;
  dailyTokens?: number;
}

/** One rule a layer sets, in the Policy pane's words (#3230): for example Per day: $40.00 a day. */
export interface PolicyRuleLine {
  rule: PolicyRuleName;
  title: string;
  words: string;
}

/** One rule a policy layer can set (#2957, data-model.md "EffectiveRule"). */
export type PolicyRuleName =
  | "permissionMode"
  | "permissionRequests"
  | "sandbox"
  | "budgets.perAgent"
  | "budgets.daily"
  | "budgets.perAgentTokens"
  | "budgets.dailyTokens"
  | "helpers.mostRunning"
  | "helpers.mostNotArchived"
  | "helpers.mostQueued"
  | "workflows.mostOn"
  | "noticeLimits.burst"
  | "noticeLimits.waitMinutes"
  | "archiveMyChats"
  | "runtimes"
  | "marketplaces.allowed"
  | "marketplaces.customServers"
  | "environment"
  | "connectorTools";

/**
 * The rules a layer sets (#2957, data-model.md "PolicyRules"): the same shape on the organisation,
 * your and a folder's layer (FR-002). Every field is optional: absent sets nothing.
 */
export interface PolicyRules {
  permissionMode?: PermissionLevel;
  permissionRequests?: ClientPermissionMode;
  sandbox?: SandboxChoice;
  budgets?: PolicyRuleBudgets;
  helpers?: PolicyHelpers;
  workflows?: PolicyWorkflows;
  noticeLimits?: PolicyNoticeLimits;
  archiveMyChats?: boolean;
  /** A runtime not named is not allowed. Absent allows every runtime and model. */
  runtimes?: Record<string, PolicyRuntimeRule>;
  marketplaces?: PolicyMarketplaces;
  environment?: PolicyEnvironment;
  /**
   * The level of each connector's tools, by the connector's name (#4099). A tool no layer names is
   * ask when it writes and allow when it only reads.
   */
  connectorTools?: Record<string, PolicyConnectorRule>;
}

/** One allowed runtime in a policy (#998). */
export interface PolicyRuntimeRule {
  /**
   * The model ids allowed, with * at the end allowed (claude-sonnet-*). Absent allows every model.
   */
  models?: string[];
  /**
   * The ways this runtime may reach the model (#999). Absent: every way. [orgKey, gateway] is the
   * org path only.
   */
  reach?: PolicyReach[];
}

/**
 * policy/set (#998): the rules, and the rev the admin read. No rev when there was no policy.
 * Refused changedElsewhere when another admin saved first.
 */
export interface PolicySet {
  policy: OrgPolicy;
  rev?: string;
}

/**
 * The mark on a choice a policy refuses or caps (#998, FR-010). layer names which layer decided
 * (#2957, R8).
 */
export interface PolicySetBy {
  by: "organisation" | "you" | "folder";
  rule: string;
  words: string;
  layer?: PolicyLayerRef;
}

/**
 * The control key's signature of a policy (#998, FR-004), kept at v1/policy.sig: ECDSA P-256 with
 * SHA-256 (es256), over the policy's canonical JSON (keys sorted, no spaces). sig is the 64 bytes r
 * then s.
 */
export interface PolicySignature {
  version: number;
  /** The first 8 bytes of the SHA-256 of the control key's X9.63 public key, base64url. */
  keyID: string;
  alg: "es256";
  sig: Base64;
}

/**
 * daemon/policyState and daemon/policyStateChanged (#998, T027): the organisation's policy as this
 * machine follows it, so a client on the direct path draws the strip and the Policy pane. No
 * version when this machine has no policy.
 */
export interface PolicyState {
  version?: number;
  /** The rules in force here, with only this machine's person's raises. */
  policy?: OrgPolicy;
  /** The kill switch is on: this machine stops its turns and starts no work. */
  stopAll: boolean;
  /**
   * This machine had a policy from its organisation and has none it can trust now (missing, or it
   * fails the signature check). It starts no work until it gets one.
   */
  noPolicy: boolean;
  /** The capabilities the policy requires that this machine lacks (FR-014). It starts no work. */
  update?: string[];
  /** Why this machine starts no work now, when it starts none. */
  refusal?: PolicyRefusal;
}

/** The kill switch (#998, FR-015): while on, every machine stops its turns and starts no work. */
export interface PolicyStopAll {
  on: boolean;
  by: AuditActor;
  at: WireDate;
  note?: string;
}

/** policy/stopAll (#998): the kill switch on or off, with an optional note. */
export interface PolicyStopAllRequest {
  on: boolean;
  note?: string;
}

/**
 * policy/mine and control/policyChanged (#998): the policy in force, for any person, with only
 * their own budget raises. No policy when none was ever set.
 */
export interface PolicyView {
  policy?: OrgPolicy;
}

/** How many workflows a layer allows turned on at once, in each folder (#2957). Unset means 20. */
export interface PolicyWorkflows {
  mostOn?: number;
}

export interface PresenceReport {
  watching?: UUID;
  active: boolean;
  mayNotify?: boolean;
  showing?: UUID;
  alsoShowing?: UUID[];
}

export interface PreviewFile {
  path: string;
  bytes: number;
  runnable: boolean;
  via: string;
}

export type PreviewProblem =
  | { noSkillFile: Record<string, never> }
  | { notFoundInRepo: Record<string, never> }
  | { tooLarge: { bytes: number; files: number } }
  | { skipped: { _0: string[] } };

export interface PrewarmRequest {
  agentID: UUID;
  why: PrewarmRequestWhy;
}

export type PrewarmRequestWhy =
  | "opened"
  | "typing";

/**
 * A problem report, ready to post (#3718): the new issue's title and body, and the GitHub page that
 * opens it already filled in, so the person posts it from their own account. Every known token
 * shape and every home folder in it is cut out (~ in place of a home), and nothing is sent
 * anywhere: the client shows the body, then opens the url.
 */
export interface ProblemReport {
  title: string;
  /**
   * Markdown: what happened, what the person expected, and the versions, the machine and the
   * runtime; with the recent log lines when asked.
   */
  body: string;
  /**
   * The repository's new-issue page with the title and body in its query. When the body is too long
   * for a link, the oldest log lines are left out of the link first, then the end of the body.
   */
  url: string;
}

/** What the person wrote in Report a Problem, and which client it is (#3718). */
export interface ProblemReportRequest {
  /** What happened, in the person's words. */
  happened: string;
  /** What the person expected. */
  expected: string;
  /** The client and its version, such as "Mac window 0.17.0" or "Web page". */
  client: string;
  /** The client's OS, such as "macOS 26.1", or the browser's. */
  clientOS: string;
  /** The runtime of the open session, when there is one. */
  runtime?: string;
  /** Add this machine's recent daemon.log lines. */
  withLog: boolean;
}

/** One process of processes/list (#3453): the daemon, a session's runtime, or a child of either. */
export interface ProcessUsage {
  pid: number;
  parent: number;
  /** 0 for the daemon; a child is one deeper than its parent. */
  depth: number;
  name: string;
  /**
   * Of one core, so more than 100 on several, over the same time as the machine's; 0 for a process
   * the last ask did not list.
   */
  cpuPercent: number;
  /** Resident bytes. */
  memory: number;
  /** The session whose runtime this is, or whose runtime started it. */
  agentId?: UUID;
  /** That session's title, when it has one. */
  title?: string;
}

/**
 * processes/list (#3453): the machine's totals and the daemon's process tree, in tree order, the
 * daemon first. At most 200 processes; omitted counts the rest.
 */
export interface ProcessesState {
  machine: MachineUsage;
  processes: ProcessUsage[];
  omitted: number;
}

/**
 * A project (#2317): what people work on, the record that folders join. folders is what the
 * machines last reported.
 */
export interface Project {
  id: string;
  name: string;
  owner: string;
  folders: ProjectFolder[];
  /**
   * The caller is the owner or an admin, so may rename and remove it, and set its slots and boards.
   */
  mayChange: boolean;
  /**
   * The project's Tasks, Code review and CI (#2669), one per slot: every folder in the project uses
   * them. A slot that is not here is each folder's own.
   */
  slots?: ProjectSlot[];
  /** The boards in the project's Tasks slot (#3282), in their order. Absent with none. */
  boards?: ProjectBoard[];
}

/**
 * One board in a project's Tasks slot (#3282): a GitHub Projects board, a Jira board, a Linear
 * team, a GitLab group board or an Azure Boards board (a team's, #3816), by its address and a name
 * (the team's). Work's Issues and Features lists narrow to one. A client sends name and url; the
 * control plane reads forge, key and site from the url.
 */
export interface ProjectBoard {
  name: string;
  /**
   * The board's address on the web: github.com/orgs/<org>/projects/<n> (or users/<login>),
   * <site>/jira/software/…/boards/<id>, linear.app/<workspace>/team/<KEY>,
   * <gitlab>/groups/<group>/-/boards/<id>, or dev.azure.com/<org>/<project>/_boards/board/t/<team>
   * (or an Azure DevOps Server's). It names the board in forge/issues' board.
   */
  url: string;
  /** github, atlassian (Jira), linear, gitlab or azuredevops (Azure Boards). */
  forge?: ConnectionProvider;
  /**
   * The board on its forge: <owner>/<number> on GitHub, the board id on Jira, the team key on
   * Linear, <group>#<id> on GitLab, <org>/<project>/<team> on Azure Boards.
   */
  key?: string;
  /**
   * The board's host: github.com, the Jira site, linear.app, gitlab.com or a self-managed GitLab,
   * dev.azure.com or an Azure DevOps Server.
   */
  site?: string;
}

/**
 * projects/setBoards (#3282): the project's boards, all of them each time, in their order; none
 * leaves Tasks with no boards. Only the owner or an admin. At most 20.
 */
export interface ProjectBoardsSet {
  id: string;
  boards: ProjectBoard[];
}

/** A folder in a project (#2317), as its machine last reported it. */
export interface ProjectFolder {
  machine: MachineRef;
  folder: URLString;
  name: string;
}

/**
 * machines/projectFolders (#3277): the project's folders on each of the person's machines, as they
 * joined it, so start_session with machine alone picks the project's folder there.
 */
export interface ProjectFolders {
  machines: ProjectMachineFolders[];
}

/** machines/projectFolders (#3277): the project. */
export interface ProjectFoldersRequest {
  project: string;
}

/** projects/list (#2317): the organisation's projects, by name. */
export interface ProjectList {
  projects: Project[];
}

/** A machine of projects/sessions (#3276) that has a folder of the project, by id and name. */
export interface ProjectMachine {
  machine: MachineRef;
  machineName: string;
}

/**
 * One machine of machines/projectFolders (#3277): its id and name, and the absolute paths of its
 * folders in the project.
 */
export interface ProjectMachineFolders {
  machine: MachineRef;
  machineName: string;
  folders: string[];
}

/** projects/remove (#2317): the project. Refused while a folder names it. */
export interface ProjectRequest {
  id: string;
}

/**
 * One session of projects/sessions (#3276): the machine it runs on, and the session as that machine
 * lists it, lean.
 */
export interface ProjectSession {
  machine: MachineRef;
  machineName: string;
  session: Agent;
}

/**
 * projects/sessions (#3276): the project's sessions on each of the caller's machines that has a
 * folder of it, newest activity first. unreached is the machines that have a folder of it but did
 * not answer (offline, or too slow): their sessions are not in sessions.
 */
export interface ProjectSessions {
  sessions: ProjectSession[];
  unreached: ProjectMachine[];
}

/** projects/sessions (#3276): the project, and whether to list archived sessions too. */
export interface ProjectSessionsRequest {
  project: string;
  includeArchived?: boolean;
}

/** projects/set (#2317): makes a project, or with id renames one. */
export interface ProjectSet {
  id?: string;
  name: string;
}

/**
 * A project's Tasks, Code review or CI slot (#2669): the forge and the repository (GitHub
 * owner/name, GitLab group/project) that fill it for every folder in the project, or skipped.
 */
export interface ProjectSlot {
  slot: ConnectorSlotKind;
  forge?: ConnectionProvider;
  repository?: string;
  /** The repository's host: github.com, gitlab.com, or a self-managed GitLab's host. */
  site?: string;
  /** Skipped for every folder in the project. forge, repository and site are then absent. */
  skipped?: boolean;
}

/**
 * projects/setSlot (#2669): sets one of the project's slots, or with no value gives it back to each
 * folder. Only the owner or an admin.
 */
export interface ProjectSlotSet {
  id: string;
  slot: ConnectorSlotKind;
  value?: ProjectSlot;
}

/** One project's slots, as a machine gets them (#2669). */
export interface ProjectTools {
  id: string;
  name: string;
  slots: ProjectSlot[];
  /** The boards in the project's Tasks slot (#3282), in their order. Absent with none. */
  boards?: ProjectBoard[];
}

/**
 * control/projectsChanged (#2317): a project was made, renamed, adopted or removed, or a folder
 * joined one.
 */
export interface ProjectsChanged {
  id?: string;
  removed?: boolean;
}

/**
 * projects/joined (#2317): a machine's folders and the project each names, all of them each time.
 */
export interface ProjectsJoined {
  folders: JoinedFolder[];
}

export type PromptOrigin =
  | "person"
  | "app"
  | "agent";

export interface PromptRequest {
  agentID: UUID;
  text: string;
  attachments: Attachment[];
  from: PromptOrigin;
  sendID?: UUID;
  /**
   * Sent from voice mode (#2322): the daemon puts the voice-mode text in front of the words, as the
   * prompt's preface.
   */
  voice?: boolean;
}

/**
 * providers/add and providers/update. `machine` is the machine that carries the provider (#3398):
 * it runs the provider's server, and `secrets` go on to it, never kept by the control plane. None
 * picks the caller's first online machine; an update without it keeps the one it has. `cli` is not
 * kept; `draft` is the draft this accepts (#858).
 */
export interface ProviderAdd {
  id?: ProviderID;
  name: string;
  kind: "commands" | "stdio" | "http";
  command?: string;
  args?: string[];
  url?: string;
  headers?: Record<string, string>;
  commands?: JSONValue;
  map?: JSONValue;
  machine?: MachineRef;
  secrets?: Record<string, string>;
  cli?: string;
  draft?: UUID;
}

/**
 * What a provider's machine answers to providers/carry, providers/keepSecrets, providers/forget and
 * providers/ssh (#3398): the call's result, or why it failed, in words for the person. Channel 0
 * has no error path.
 */
export interface ProviderCarried {
  result?: JSONValue;
  error?: string;
}

/**
 * providers/carry (#3398): the control plane asks the machine that carries a provider to call it.
 * `record` is the provider's record, which never holds a secret; the machine runs its server with
 * the secrets it keeps. `secrets` is only a draft's, for this call, and is not kept.
 */
export interface ProviderCarry {
  provider: ProviderID;
  record: JSONValue;
  call: "check" | "list" | "start" | "stop" | "options" | "create" | "delete" | "tools";
  workspace?: string;
  name?: string;
  options?: JSONValue;
  firstBoot?: string;
  secrets?: Record<string, string>;
}

/**
 * providers/create. With no `id`, the person's default provider: the first one added that they may
 * make machines from (#3972). With no `name`, `machine-N`, from the person's own counter. With no
 * `options`, the provider's defaults: each field's `default`, or else the first of its `enum`.
 */
export interface ProviderCreate {
  id?: ProviderID;
  name?: string;
  options?: JSONValue;
  clones?: string[];
  /**
   * The repository to start it from (#1809), an https git address. A provider whose New Machine
   * form has `repository`, such as Codespaces, makes the workspace from it; any other has the host
   * clone it once it joins, before `clones`.
   */
  repository?: string;
}

/** What providers/create made. */
export interface ProviderCreated {
  workspace: MachineInfo;
  joining: boolean;
}

/** providers/draftAnswer: yes or no to a question. */
export interface ProviderDraftAnswer {
  draft: UUID;
  question: UUID;
  yes: boolean;
}

/** A draft answered with no agent: the server follows the contract, or a shipped map fits. */
export interface ProviderDraftAnswered {
  note: string;
  map?: JSONValue;
  preset?: string;
}

/** providers/draftCancel. */
export interface ProviderDraftRequest {
  draft: UUID;
}

/**
 * The writing agent's start, for the client that asked for the draft to sign (#3542): the machine
 * that holds its person's lock takes no start the control plane sends in its own words. The client
 * checks that it starts only a draft's writer (agents/start, the draft's purpose, sandboxed, no MCP
 * servers or other folders), signs method and params as they are (a LockSignature to machine), and
 * sends the signature with providers/draftSigned.
 */
export interface ProviderDraftSign {
  machine: MachineRef;
  method: string;
  params: string;
}

/**
 * providers/draftSigned (#3542): the signature of a draft's sign, which the control plane delivers
 * with the start as it came.
 */
export interface ProviderDraftSigned {
  draft: UUID;
  lock: LockSignature;
}

/** providers/draftStart (#858). */
export interface ProviderDraftStart {
  form: ProviderAdd;
  secrets?: Record<string, string>;
  provider?: ProviderID;
  runtimeID: string;
}

export interface ProviderDraftStarted {
  draft: UUID;
  answered?: ProviderDraftAnswered;
  sign?: ProviderDraftSign;
}

/** control/providerDraft: how a draft stands, to the client that started it. */
export interface ProviderDraftUpdate {
  draft: UUID;
  state: string;
  runtimeName: string;
  steps: DraftStep[];
  cost?: string;
  draftJSON?: JSONValue;
  check?: DraftCheck;
  question?: DraftQuestion;
  note?: string;
}

/**
 * providers/forget (#3398): the provider was removed; its machine ends its server and deletes its
 * secrets.
 */
export interface ProviderForget {
  provider: ProviderID;
}

/**
 * providers/setGroup (#1761): the group whose users may use the provider. No group is the admins'
 * alone.
 */
export interface ProviderGroup {
  provider: ProviderID;
  group?: string;
}

/** providers/list and control/providersChanged. */
export interface ProviderList {
  providers: ProviderSummary[];
}

/**
 * providers/options: the New Machine form, a JSON Schema, with what New Machine would make (#4634).
 * With no `id`, the person's default provider.
 */
export interface ProviderOptions {
  schema: JSONValue;
  /** The provider the form is for: the one asked for, or else the person's default. */
  id?: ProviderID;
  /**
   * The values the form starts with: the options the person made a machine with last on this
   * provider, over each field's `default` or else the first of its `enum`.
   */
  values?: JSONValue;
  /**
   * The name New Machine would give: the person's next `machine-N`. Not kept until a make uses it.
   */
  name?: string;
}

/** providers/remove, providers/refresh, providers/options (with no `id`, the default provider). */
export interface ProviderRequest {
  id?: ProviderID;
}

export interface ProviderRuntime {
  id: string;
  name: string;
  isDefault: boolean;
}

/** providers/runtimes: what may write, on which host, or why none. */
export interface ProviderRuntimes {
  runtimes: ProviderRuntime[];
  host?: string;
  why?: string;
}

/**
 * providers/ssh (#3398): the machine that carries a codespaces provider starts a codespace's
 * agentsd over ssh (`start`), reads its host key (`hostKey`), installs Agents in it with a host
 * code from the control plane (`install`, #3497), or holds an ssh session to it that GitHub counts
 * as use while its machine works (`keepAwake`, renewed each few minutes, and `letSleep`, #4637),
 * with the token it keeps. Its result is ProviderSSHResult.
 */
export interface ProviderSSH {
  provider: ProviderID;
  op: "start" | "hostKey" | "install" | "keepAwake" | "letSleep";
  /**
   * install's host code: the codespace runs the control plane's install.sh with it, from the
   * address and pin it names.
   */
  hostCode?: string;
  destination: string;
  /** The codespace's name, for gh. */
  codespace?: string;
  knownHosts?: string;
  name?: string;
  renew?: boolean;
  trust?: string;
}

/**
 * providers/ssh's result (#3398): the host key taken, in known_hosts form, and for hostKey a
 * fingerprint to trust first.
 */
export interface ProviderSSHResult {
  knownHosts?: string;
  needsTrust?: string;
}

/**
 * providers/keepSecrets (#3398): secrets for a provider the machine carries, laid over what it has
 * in ~/.agents-secrets; an empty value takes one away. The control plane passes them on and keeps
 * none.
 */
export interface ProviderSecretsKeep {
  provider: ProviderID;
  secrets: Record<string, string>;
}

/** A provider for the Providers page, never its commands, headers or secrets' values. */
export interface ProviderSummary {
  id: ProviderID;
  name: string;
  kind: string;
  secrets: Record<string, boolean>;
  capabilities: string[];
  contract: number;
  mapped: boolean;
  preset?: string;
  workspaces: MachineInfo[];
  listedAt?: WireDate;
  current: boolean;
  problem?: string;
  /** The group whose users may use it (#1761); none is the admins' alone. */
  group?: string;
  /**
   * The caller may start machines from it (#1761): they are in its group. Absent from an older
   * control plane, which lets everyone.
   */
  mayUse?: boolean;
  /**
   * New Machine makes the caller's machines on it (#3979): the one they made a machine on last or
   * chose with Make Default, or else the first one added. True on one provider at most; absent from
   * an older control plane.
   */
  default?: boolean;
  /**
   * The machine that carries it: runs its server and keeps its secrets (#3398). Absent for one made
   * before, which must be added again.
   */
  machine?: MachineRef;
  machineName?: string;
  /**
   * Its machine is offline: its machines can't be started, stopped, made or deleted until it is
   * back (#3398).
   */
  machineOffline?: boolean;
  /**
   * The CLI its machines are reached through over ssh (gh, coder) when the control plane's machine
   * has none (#3367). Absent when it needs none or has it.
   */
  sshToolMissing?: string;
}

/**
 * providers/deleteWorkspace (#4610): one of a provider's workspaces that no machine is linked to.
 */
export interface ProviderWorkspaceRequest {
  id: ProviderID;
  workspace: string;
}

/**
 * Which APNs a device token belongs to (#1460): a Debug build's (sandbox) or a TestFlight and App
 * Store build's.
 */
export type PushEnvironment =
  | "development"
  | "production";

/**
 * clients/setPushToken (#1460): a device's own APNs token, in hex, for the control plane to push
 * its notices to. No token takes it away.
 */
export interface PushToken {
  token?: string;
  environment: PushEnvironment;
}

export interface QueuedPrompt {
  id: UUID;
  text: string;
  attachments: Attachment[];
  queuedAt: WireDate;
  from: PromptOrigin;
  preface?: string;
  sender?: MessageSender;
}

export interface QueuedStart {
  runtimeID?: string;
  permissionMode?: string;
  model?: string;
  worktree?: WorktreeChoice;
  labels: string[];
}

export interface QuickAnswer {
  kind: QuickAnswerKind;
  id: string;
  title: string;
  field?: string;
  isDestructive: boolean;
}

export type QuickAnswerKind =
  | "choice"
  | "reply";

export interface QuitRequest {
  stopAgents: boolean;
}

export interface RateLimitInfo {
  status?: string;
  resetsAt?: WireDate;
  rateLimitType?: string;
  utilization?: number;
  overageStatus?: string;
  overageResetsAt?: WireDate;
  isUsingOverage?: boolean;
  overageInUse?: boolean;
  overageDisabledReason?: string;
}

/**
 * readApi/list (#2019), an admin's: the read API's tokens, newest first, revoked ones too; its URL;
 * and the OTLP exporter when one is set.
 */
export interface ReadAPI {
  tokens: ReadToken[];
  url: string;
  otlp?: OTLPExport;
}

/**
 * A read API token (#2019, #1804 decision 4), with no value: the control plane keeps only its
 * SHA-256. It reads the organisation's reports at /v1/read/reports, and nothing else.
 */
export interface ReadToken {
  id: string;
  name: string;
  made: OrgRouteStamp;
  lastUse?: SCIMTokenUse;
  revoked?: OrgRouteStamp;
}

/** readApi/make (#2019): the token, its value once (never shown again), and the URL to read. */
export interface ReadTokenMade {
  token: ReadToken;
  value: string;
  url: string;
}

/** readApi/make (#2019): a name for the token, such as the BI tool that uses it. */
export interface ReadTokenMake {
  name: string;
}

/** readApi/revoke (#2019): the token to stop at once. */
export interface ReadTokenRevoke {
  id: string;
}

/**
 * Makes or brings up to date a host's copy of a Mac's repository (#1123): fetches the `bundle`
 * upload, moves `branches` forward only, checks out `checkout`, sets `origin`, applies the `patch`
 * upload (uncommitted changes), and adds the folder as a folder. It stops, and changes nothing,
 * when the host has changes or commits of its own.
 */
export interface ReceiveRequest {
  folder: string;
  bundle?: UUID;
  patch?: UUID;
  branches: SentBranch[];
  checkout: string;
  origin?: string;
}

/**
 * What a host has at a folder before a send (#1123). `heads` are the commits of its branches, so
 * the Mac's bundle carries only what the host lacks. `ownChanges` is true when the folder has
 * changes that the last send did not put there.
 */
export interface ReceiveState {
  folder: URLString;
  exists: boolean;
  repository: boolean;
  ownChanges: boolean;
  heads: string[];
}

/**
 * Asks a host about a folder a Mac will send a repository to (Send to ‹host›…, #1123). `folder` may
 * start with ~/.
 */
export interface ReceiveStateRequest {
  folder: string;
}

/**
 * One part of a file a Mac sends (#1123), at `offset` in the upload. A part is at most 16 MB; the
 * host keeps the upload until folders/receive uses it.
 */
export interface ReceiveUploadRequest {
  upload: UUID;
  offset: number;
  data: Base64;
}

/**
 * A notice for one device (T097), which the control plane sends through APNs or Web Push: seal the
 * headline to `publicKey` and post it for `device`; no headline is a withdrawal.
 */
export interface RelayDelivery {
  needID: NeedID;
  device: UUID;
  publicKey?: Base64;
  headline?: Headline;
  alert: boolean;
  waiting?: number;
  /**
   * Asked by an agent that holds the person's booking (person:<name>, #4268): notify it as timely
   * (Time Sensitive on iOS, an alert on the Mac, an urgent Web Push).
   */
  timely?: boolean;
}

export interface RelayGrantReply {
  runtime: string;
  caCertificate: string;
  standIn: string;
}

export interface RelayGrantRequest {
  runtime: string;
}

export interface RelayOffer {
  runtime: string;
  socketPath: string;
  caCertificate: string;
  standIn: string;
}

/**
 * The tokens the machine's model relay counted from the provider's own answers (#999, FR-019):
 * fresh input, output, and cache reads and writes.
 */
export interface RelayTokens {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
}

export interface RememberedOptionsRequest {
  runtimeID: string;
  cwd: URLString;
}

export interface RemovalCheck {
  blockedBy: UUID[];
  uncommitted: number;
  unmerged: boolean;
}

/**
 * A Remove request (#1002, D13, FR-017): an org provider deleted a person by SCIM; the person is
 * suspended, and an admin confirms the removal with people/remove.
 */
export interface RemoveRequest {
  user: string;
  name: string;
  provider: string;
  at: WireDate;
}

/** people/removeRequests (#1002): the Remove requests waiting for an admin, oldest first. */
export interface RemoveRequestList {
  requests: RemoveRequest[];
}

export interface RemoveResourceRequest {
  name: string;
}

export interface RenameRequest {
  agentID: UUID;
  title: string;
}

/**
 * What a machine's agents did in an hour or a day (#2019, R2 to R6), counted from its own event log
 * and its time ledger: never a conversation's words. Absent from a machine before #2019.
 */
export interface ReportCounts {
  /** Agents that began their first turn (agent.started). */
  sessions: number;
  /** Agents that ended in an error that nobody chose (agent.failed). */
  failedSessions: number;
  /** Pull and merge requests opened from an agent's branch on this machine (pr.opened). */
  prsOpened: number;
  /** Those merged (pr.merged). */
  prsMerged: number;
  /** Of those merged, the ones that revert another: a title that starts with "Revert". */
  prsReverted: number;
  /**
   * The merged ones' time from their agent's start to the merge, added up: divide by prsMerged for
   * the mean.
   */
  mergeSeconds: number;
  /** The times an agent waited for its person in a turn (a question, a form, a permission). */
  waits: number;
  /** The waits by how long each was: under 1 minute, 5, 15, 60, 240, and longer. Six numbers. */
  waitBuckets: number[];
  /** Runs a workflow started (workflow.ran). */
  workflowRuns: number;
  /** Runs whose agent ended in an error (agent.failed of an agent a workflow started). */
  workflowFailures: number;
}

/**
 * How far the estimates were from the actual figures (#3561), over the issues closed in the range
 * that had an estimate when their work started: the median of max(estimate/actual,
 * actual/estimate), so 1.5 means 1.5 times too high or too low. A figure is absent when no issue
 * had it. coverage and landsAtErrorDays (#4525) check the claims the kept estimate made: how often
 * its P10-P90 dollar range held the actual, and how many days its landing date was off by, the
 * median over the same issues.
 */
export interface ReportEstimateError {
  /** The closed issues with an estimate. */
  issues: number;
  /** In US dollars. */
  cost?: number;
  /** In the agents' time at work. */
  workingSeconds?: number;
  /**
   * How often the kept estimate's P10 to P90 dollar range held the actual, 0 to 1; it should be
   * about 0.8 (#4525).
   */
  coverage?: number;
  /** The median of how many days the kept landing date was off by (#4525). */
  landsAtErrorDays?: number;
}

/** reports/export's answer (#1811): the rows as CSV or JSON lines. */
export interface ReportExport {
  text: string;
  count: number;
  format: ReportFormat;
}

/**
 * How the kept landing forecasts scored (#4528): of the epics that landed in the range with a
 * forecast kept on their node (lineage/forecast's first one, #4526), how many landed by its P50
 * date and by its P85 date. A good P85 holds about 85% of the time, and a P50 about half. errorDays
 * is the median of how many days the P50 date was off by. An epic lands when the last PR of it or
 * its children merges.
 */
export interface ReportForecastScore {
  epics: number;
  p50Held: number;
  p85Held: number;
  errorDays?: number;
}

export type ReportFormat =
  | "csv"
  | "jsonl";

/**
 * One row of reports/nodes (#3118): an issue, PR or release, its cost rolled up from every machine
 * in the scope as reports/value adds it up. own is what was banked on the node itself; total adds
 * its parts (an issue's PRs; a release's issues and PRs); waste is the parts' PRs closed without a
 * merge or reverted. sessions is how many sessions worked on it and its parts, each once.
 * leadTimeSeconds is from the first work on it to its last PR merged, absent before a merge.
 * resolved is the newest title, state and labels any machine sent; absent when none had them.
 */
export interface ReportNode {
  node: LineageNode;
  /** The repo or tracker the node is in, as LineageCostNode's. */
  repo?: string;
  resolved?: LineageResolved;
  cost: ReportNodeCost;
  sessions: number;
  leadTimeSeconds?: number;
  /**
   * From the start of work on it (its own, its PRs' or, for an epic, its children's startedAt) to
   * its last PR merged (#3562); absent before a merge or with no start.
   */
  cycleTimeSeconds?: number;
  /** The first start of work on it or its parts (#3562). */
  startedAt?: WireDate;
  /** An issue's level, as LineageCostNode's (#3562). */
  level?: string;
  feature?: string;
  /** A PR's end, as LineageCostNode's; absent while open. */
  outcome?: string;
  /** The last change to it or any of its parts. */
  lastAt: WireDate;
}

/** A reports/nodes row's cost (#3118). */
export interface ReportNodeCost {
  own: LineageCost;
  total: LineageCost;
  waste: LineageCost;
}

/**
 * reports/nodes' answer (#3118): a page of at most 100 nodes. cursor asks for the next page; absent
 * on the last. limited says there are more pages. unresolved is how many nodes of the kind no
 * machine sent a title, state or labels for: a state or label filter matches none of them.
 */
export interface ReportNodes {
  nodes: ReportNode[];
  cursor?: string;
  limited: boolean;
  unresolved: number;
}

/**
 * reports/nodes (#3118): the lineage nodes of one kind in a scope, with filters and pages. The
 * scope is as reports/value's. state is open, closed or merged, from the node's resolved state (a
 * PR with none falls back to its outcome); releases have no state in v1. repo is a repo's ref
 * (github:repo:#alexec/agents; the old github:alexec/agents is read too). since is on the node's
 * last change. limit is 1 to 100, 50 when absent. cursor is the last page's, opaque.
 */
export interface ReportNodesQuery {
  /** issue, pr or release. */
  kind: string;
  state?: string;
  repo?: string;
  label?: string;
  since?: WireDate;
  sort?: ReportNodesSort;
  cursor?: string;
  limit?: number;
  /** Me, a group or the organisation (#1804). */
  scope?: ReportScope;
}

/**
 * newest (the last change first; the default), cost (total, the most first), waste (the most first)
 * or leadTime (the longest first; nodes with none last).
 */
export type ReportNodesSort =
  | "newest"
  | "cost"
  | "waste"
  | "leadTime";

/** A page of Reports (#1804, #2019). */
export type ReportPage =
  | "spend"
  | "outcomes"
  | "time"
  | "runtimes"
  | "adoption"
  | "workflows"
  | "value";

/** Who sees what in Reports (#1804), set by an admin in Console ▸ Report Policy. */
export interface ReportPolicy {
  /**
   * A group lead sees the group's totals only, with no person or machine named. An admin always
   * sees each person.
   */
  totalsOnly: boolean;
  /** Each group's leads, by group id: users who see the group's reports. */
  leads: Record<string, string[]>;
  /** A budget for a calendar month in US dollars, by group id, or "org" for the organisation. */
  budgetsUSD: Record<string, number>;
}

/**
 * reports/usage and reports/export (#1811). With no scope, an admin sees every person and a member
 * their own machines; a scope (#1804) is one the caller may see (reports/scopes).
 */
export interface ReportQuery {
  range: ReportRange;
  /** For reports/export; CSV when absent. */
  format?: ReportFormat;
  /** Me, a group or the organisation (#1804). */
  scope?: ReportScope;
}

/** D is the last 24 hours by the hour; W, M and 3M the last 7, 30 and 90 days by the day (UTC). */
export type ReportRange =
  | "day"
  | "week"
  | "month"
  | "threeMonths";

/** One hour or day of one machine's folder and runtime, with its person (#1811). */
export interface ReportRow {
  /** The UTC hour ("2026-10-21T15") or day ("2026-10-21"). */
  at: string;
  person: string;
  personName: string;
  host: MachineRef;
  hostName: string;
  runtime: string;
  /**
   * The workflow that started the agents of this row (#2019), by its id; absent for agents a person
   * or another agent started.
   */
  workflow?: string;
  /** By currency. */
  cost: Record<string, number>;
  inputTokens: number;
  outputTokens: number;
  thoughtTokens: number;
  cachedReadTokens: number;
  cachedWriteTokens: number;
  turns: number;
  unpricedTurns: number;
  /** The agent, its tools and waiting on others: TimeBucket's agent + tools + others. */
  workingSeconds: number;
  /** Waiting for the person: TimeBucket's person. */
  waitingSeconds: number;
  /**
   * The groups the person is in (#1804), by id, for a group or organisation scope; absent when the
   * person is hidden.
   */
  groups?: string[];
  /** What the agents did (#2019): sessions, pull requests and waits. */
  counts?: ReportCounts;
  folder: string;
  /**
   * The project the folder is in (#2670), by id, as its machine last reported it (projects/joined);
   * absent for a folder in no project.
   */
  project?: string;
  /** The project's name, absent with project. */
  projectName?: string;
}

/** Whose rows a report adds up (#1804). */
export interface ReportScope {
  kind: ReportScopeKind;
  /** The group's id, for kind group. */
  group?: string;
}

/** Me (the caller's own machines), a group's people, or every person (#1804). */
export type ReportScopeKind =
  | "me"
  | "group"
  | "org";

/** A scope the caller may see, with its name (#1804). */
export interface ReportScopeOption {
  scope: ReportScope;
  name: string;
}

/**
 * reports/scopes' answer (#1804): Me, each group the caller leads (every group for an admin), and
 * the organisation for an admin.
 */
export interface ReportScopes {
  scopes: ReportScopeOption[];
  admin: boolean;
}

/**
 * reports/value (#2351): what the work in a scope cost and what it delivered, from the lineage
 * nodes that the scope's machines send (#2350). A node is in the range when it last changed in it,
 * with its whole cost. total is the work on issues, PRs and releases (a release session's own,
 * #4524); waste is the PRs closed without a merge and merged reverts; unlinked is the turns with no
 * issue or PR. perMergedPR is total by the PRs merged, by currency. leadTimeSeconds is the median
 * of the issues' lead times. issues and releases (#3023) are the most costly first, at most 100
 * each; limited says there are more.
 */
export interface ReportValue {
  range: ReportRange;
  scope: ReportScope;
  total: LineageCost;
  waste: LineageCost;
  unlinked: LineageCost;
  /** total and unlinked together (#4524): what the work cost all in, as the agents spent it. */
  loaded?: LineageCost;
  /** The scope's overhead over the 14 days to now (#4524), whatever the range. */
  overhead?: LineageOverhead;
  /** By currency. */
  perMergedPR: Record<string, number>;
  prsMerged: number;
  prsClosed: number;
  prsReverted: number;
  failedChecks: number;
  leadTimeSeconds?: number;
  /** The median of the issues' cycle times (#3562). */
  cycleTimeSeconds?: number;
  estimateError?: ReportEstimateError;
  /**
   * How the kept landing forecasts of the epics that landed in the range scored (#4528); absent
   * when none had one.
   */
  forecastScore?: ReportForecastScore;
  /**
   * The open epics in the scope (#4528), the most recently changed first, at most 20, so Reports ▸
   * Planning can ask lineage/forecast when each lands.
   */
  openEpics?: LineageNode[];
  issues: ReportValueRow[];
  /** One row per release (#3023): the PRs part-of it and the issues those PRs fix. */
  releases: ReportValueRow[];
  limited?: boolean;
}

/**
 * One issue or release on Reports ▸ Value (#2351): its cost rolled up from every machine in the
 * scope, as lineage/cost adds it up, and how its PRs ended.
 */
export interface ReportValueRow {
  node: LineageNode;
  total: LineageCost;
  waste: LineageCost;
  prsMerged: number;
  prsClosed: number;
  prsReverted: number;
  failedChecks: number;
  /** From the first work on it to its last PR merged; absent before a merge. */
  leadTimeSeconds?: number;
  /** From the start of work on it to its last PR merged, as ReportNode's (#3562). */
  cycleTimeSeconds?: number;
  /** An issue's level, as LineageCostNode's (#3562). */
  level?: string;
}

/**
 * A saved view of Reports (#2019, R8): a page with its scope, range and way to add up, kept for the
 * person who saved it.
 */
export interface ReportView {
  /** Given by the control plane; empty to save a new view. */
  id: string;
  name: string;
  page: ReportPage;
  scope: ReportScope;
  range: ReportRange;
  /** The way the page adds up: person, folder, machine, runtime, group or workflow. */
  by?: string;
}

/** reports/deleteView (#2019). */
export interface ReportViewID {
  id: string;
}

/** The caller's saved views of Reports (#2019), in the order they were saved. */
export interface ReportViews {
  views: ReportView[];
}

export interface ReportedEdit {
  path: string;
  oldText?: string;
  newText: string;
  toolCallID: string;
  index: number;
  entryIndex: number;
  replaceAll: boolean;
  at: WireDate;
}

/**
 * Something an agent asked a person for (#3862, spec 3862 §1): a question, a secret, a step. Kept
 * in <root>/requests/<id>.json, an ended one for 14 days.
 */
export interface Request {
  /** For an app request, the same id as its ElicitationRequest. */
  id: UUID;
  kind: RequestKind;
  source: RequestSource;
  state: RequestState;
  /** One line, for the row. */
  title: string;
  detail: RequestDetail;
  /** The folder's URL. */
  folder: string;
  /** The session that asked. */
  askedBy?: UUID;
  /**
   * A forge item's (#3865): an issue labelled alex-todo or needs-account, or a pull request
   * labelled needs-approval.
   */
  forge?: RequestForge;
  /** Every session that waits on it; the asker first. Kept as history once it ends. */
  waiters: RequestWaiter[];
  askedAt: WireDate;
  answeredAt?: WireDate;
  answeredBy?: AuditActor;
  /** A summary for the row; never a secret's value. */
  answer?: string;
  droppedWhy?: RequestDroppedWhy;
  /**
   * Later (#4233): the request is still open, but out of Needs you, the counts and the notices
   * until it comes back. Absent when it is not deferred; an answer or a drop clears it.
   */
  deferred?: RequestDeferral;
}

/**
 * One of the answers: form for a question, a secret or a step (#3863); checklist and approval for a
 * forge item (#3865); secretUse for the use of a secret with Ask before use (#4015).
 */
export interface RequestAnswer {
  form?: RequestFormAnswer;
  checklist?: RequestChecklistAnswer;
  approval?: RequestApprovalAnswer;
  secretUse?: RequestSecretUseAnswer;
}

/**
 * A needs-approval pull request's answer: approve adds approved, changes adds changes-wanted; the
 * note is the person's comment on it.
 */
export interface RequestApprovalAnswer {
  action: "approve" | "changes";
  note?: string;
}

/**
 * The checklist's lines now ticked, by index. When every line is ticked, the request is answered.
 */
export interface RequestChecklistAnswer {
  done: number[];
}

export interface RequestChecklistLine {
  text: string;
  done: boolean;
}

/**
 * When a deferred request comes back (#4233): at until, or when the person is next at the Mac
 * (atMac: the Mac's presence changes from not here to here), whichever is first.
 */
export interface RequestDeferral {
  until?: WireDate;
  atMac?: boolean;
  /** When it was deferred. */
  at: WireDate;
  by?: AuditActor;
}

/** The part of a request that depends on its source. */
export interface RequestDetail {
  elicitation?: ElicitationRequest;
  secretUse?: RequestSecretUse;
}

export type RequestDroppedWhy =
  | "askerEnded"
  | "folderArchived"
  | "forgeClosed"
  | "restarted"
  | "byPerson";

/** The forge item a request is (spec 3862 §4). */
export interface RequestForge {
  /** github, gitlab, forgejo, … */
  provider: string;
  repo: string;
  item: "issue" | "pr";
  number: number;
  url: string;
  /** alex-todo, needs-account or needs-approval. */
  label: string;
  /** An issue's lines under its first "## What <name> does" heading. */
  checklist: RequestChecklistLine[];
  /** A pull request's image links under its "## Screenshots" heading. */
  screenshots?: string[];
  author?: string;
  /** The item's, when it was last read: a newer one is read again. */
  updatedAt?: WireDate;
  /** The last sweep that saw it open with the label. */
  seenAt: WireDate;
}

/** The answer elicitations/answer takes, for a question, a secret or a step. */
export interface RequestFormAnswer {
  action: AnswerElicitationRequestAction;
  content?: Record<string, JSONValue>;
}

export type RequestKind =
  | "decide"
  | "approve"
  | "account"
  | "step"
  | "secret";

/**
 * A use of a secret with Ask before use (#4015), waiting on a person: its kind is approve. It names
 * the secret, never its value, and where agentsd puts the value.
 */
export interface RequestSecretUse {
  name: string;
  use: SecretUse;
  /**
   * Where the value goes: the page's domain for a fill, owner/repo for CI, the server's name for an
   * MCP server, for terminal the name of the command that ran agents-secret, as that command says
   * it, and for account the account's id, as manage_accounts list gives it.
   */
  place: string;
  /**
   * For account (#4163): the manage_accounts call that waits, such as get. name is then the
   * account's service and address.
   */
  call?: string;
  /** For screen (#4264): the app drive_screen names in the call that asks. */
  app?: string;
  /**
   * The secret is the session's own (#3548): Always Approve is the same as Approve for This
   * Session.
   */
  sessionOnly?: boolean;
  /**
   * The machine is Linux (#4058): the value opens only with the release key its control plane
   * keeps, which the control plane gives only for an approval the person's client signed. An answer
   * that allows the use carries approval; one without it is refused.
   */
  needsSignature?: boolean;
}

/**
 * A person's answer to a secret's use (#4015). once allows this use; session every use at this
 * place until the session ends or is archived; always adds a grant for this place, for every
 * session; hour (terminal only, #4179) allows every call of agents-secret NAME with no session's
 * grant for one hour, kept in agentsd's memory only; deny refuses it. A terminal's use takes once,
 * hour or deny. Only the control and device roles answer.
 */
export interface RequestSecretUseAnswer {
  action: "once" | "session" | "always" | "hour" | "deny";
  /**
   * The answering client's signature of its answer (#4058), required when the request says
   * needsSignature and the action is not deny: method secrets/approveUse, params the JSON text
   * {"request":<the request's id>,"name","use","place","action"} as the request names them, and a
   * LockSignature to this machine by the client's lock key. The machine checks it against its lock
   * and sends it to the control plane, which gives the release key only for a fresh one it has not
   * seen.
   */
  approval?: LockDelivery;
}

