/** One row of user/secretNames (#1760): a secret's name, never its value. */
export interface UserSecretRow {
  name: UserSecretName;
  kind?: UserSecretKind;
  updated: string;
  /** The machines it was sent to. */
  machines: MachineRef[];
  /**
   * When the name was first set (#4158); Replace… does not change it. Left out for one set before
   * it was kept.
   */
  created?: string;
  /**
   * The value's last 4 characters (#4158), from a machine that holds a copy: only for a value of 16
   * characters or more, and a card's is the last 4 of its number. Left out otherwise. The control
   * plane passes it to the person's own clients and never writes it to its store.
   */
  hint?: string;
  lastOp?: SecretLastOp;
  /** False when one copy only opens (#4158): machines has one and waiting is empty. */
  backedUp?: boolean;
  /** Machines removed with it on them, since it was last set. */
  leftOn?: SecretLeftOn[];
  version?: number;
  /**
   * The person's machines that have no copy yet: they wait for one of the person's clients to seal
   * it (#3397).
   */
  waiting?: MachineRef[];
  /**
   * Ask before use (#4014), as the person's client last sealed it. The machines check it: the
   * associated data binds it.
   */
  needsApproval?: boolean;
  /**
   * A secret's description (#4167): one or two sentences on what it is and what it is for, such as
   * which account and scopes. Not secret, and not sealed: the control plane may keep it. Never a
   * value. Left out when it has none.
   */
  description?: string;
}

/**
 * user/setSecret (#1760, FR-025, #3397): a secret as the person's client sealed it to each
 * recipient of user/secretRecipients, info com.alexecollins.agents.usersecret.v1, associated data
 * usersecret.v1|<person id>|<recipient>|<name>|<version>. version is above the kept one: the kept
 * one plus one, or for a name the client has none of, the time in milliseconds, above a removed
 * one's. The control plane never has the value.
 */
export interface UserSecretSet {
  name: UserSecretName;
  kind?: UserSecretKind;
  version: number;
  /** By recipient. */
  values: Record<string, SealedEnvelope>;
  /**
   * Ask before use (#4014): when on, every envelope's associated data ends |ask
   * (usersecret.v1|<person id>|<recipient>|<name>|<version>|ask), so the control plane cannot
   * change it. Left out is off, and the associated data is as before.
   */
  needsApproval?: boolean;
  /**
   * A secret's description (#4167): one or two sentences on what it is and what it is for, such as
   * which account and scopes. Not secret, and not sealed: the control plane may keep it. Never a
   * value. Left out when it has none.
   */
  description?: string;
}

/**
 * user/settings (#1760, #2410): the person's settings that follow them to each of their machines.
 * An omitted part has no value yet, but does not make that setting machine-local. The control plane
 * does not read inside a part.
 */
export interface UserSettings {
  mcpServers?: JSONValue;
  agentConfig?: JSONValue;
  /** Per-file agent configuration state (#2129), with tombstones and logical timestamps. */
  agentConfigFiles?: AgentConfigFiles;
  runtimes?: JSONValue;
  costLimits?: JSONValue;
  /** The person's notice limits (#2859), as a NoticeLimits. */
  notifications?: JSONValue;
  /**
   * The person's outside accounts (#3967), as an OutsideAccounts. The control plane refuses one
   * with a value that looks like a secret.
   */
  accounts?: JSONValue;
  /**
   * The person's time zone (#4818), as a UserTimeZone. Their Mac sets it from its own clock; a
   * workflow's hours: with no time-zone: go by it.
   */
  timeZone?: JSONValue;
  /**
   * #2957, research R11: your layer, as a SignedYourPolicy. Only the keeper sets it
   * (user/setPolicy); a client cannot (user/setSettings refuses this part).
   */
  policy?: JSONValue;
  /** When a part last changed. */
  updated?: string;
}

/**
 * control/userSettingsChanged (#1760): to the person's own clients, when a part or a secret
 * changed, so a pane reads again.
 */
export interface UserSettingsChanged {
  parts?: UserSettingsPartName[];
  /** A per-file agent configuration change (#2129). */
  agentConfigFiles?: boolean;
  secrets?: boolean;
}

/** user/setSettings (#1760): one part set, or with a null value removed from the user scope. */
export interface UserSettingsPart {
  part: UserSettingsPartName;
  value: JSONValue;
}

/**
 * A part of a person's user settings (#1760, #2410). Each part has one fixed scope: MCP servers,
 * agent configuration, runtimes, cost limits, notices (#2859), outside accounts (#3967) and the
 * time zone (#4818) follow the person. Resources belong to each machine. policy (#2957) is set only
 * by the keeper, through user/setPolicy; user/setSettings refuses it.
 */
export type UserSettingsPartName =
  | "mcpServers"
  | "agentConfig"
  | "runtimes"
  | "costLimits"
  | "notifications"
  | "accounts"
  | "timeZone"
  | "policy";

