/**
 * Whether this Mac is kept awake for agents, and for how long after they stop (024), as wake.json
 * in the root.
 */
export interface WakeSettings {
  keepsAwake: boolean;
  graceHours: number;
  /**
   * How many finished sessions keep their runtime running, ready for a reply (#183, #4044): 0 to 8,
   * default 3, 0 turning the warm pool off. A runtime with background processes does not count
   * against it.
   */
  warmRuntimes: number;
  awakeOnPower: boolean;
  /**
   * How long a finished runtime whose background processes (a dev server, a build, a watcher) still
   * run is kept, counted from its last turn's end (#4044): 1 to 24 hours, default 4. Its processes
   * are then ended with it. 0, or missing, from a client that does not know it, keeps the value the
   * host has.
   */
  backgroundHours?: number;
  /**
   * How long a finished runtime with no background processes is kept, counted from its last turn's
   * end, before the host ends it (#4044, #4513): 0 to 1440 minutes, default 10. An agent that waits
   * for an event (wait_for_event, check_again, a lease) is then continued with session/load when
   * the event comes. 0 releases none for being idle; warmRuntimes still holds. Missing, from a
   * client that does not know it, keeps the value the host has. A runtime that can neither load nor
   * resume a conversation is kept while its agent waits.
   */
  releaseAfterMinutes?: number;
}

/** Why the Mac is, or is not, being kept awake (024). */
export interface WakeState {
  isHolding: boolean;
  agentsInFlight: number;
  heldBackByBattery: boolean;
  batteryPercent?: number;
  since?: WireDate;
  graceUntil?: WireDate;
  onPower: boolean;
}

