/**
 * Read forgivingly (Workflow.swift's init(from:)): a field that is missing or does not read takes
 * its default (`isEnabled` true; false, 0, [] or absent for the rest).
 */
export interface WorkflowSummary {
  scope?: "folder" | "user";
  content?: string;
  workflow: Workflow;
  isArchived: boolean;
  isEnabled: boolean;
  overLimit?: WorkflowLimit;
  totalLimit?: number;
  nextFireAt?: WireDate;
  nextFireAtByTrigger: (WireDate | null)[];
  lastOutcome?: WorkflowOutcome;
  causingEvent?: number;
  causingEventName?: string;
  isRunning: boolean;
  /**
   * A bot's workflow that does not run here (#2027): the bot's name. This machine hears its server
   * triggers with its own servers, once approved here, and sends each match to the control plane,
   * which runs it on one of the bot's machines. Nothing of it runs here.
   */
  hearsFor?: string;
  /**
   * When the daemon wrote a newer ready-made version over this unedited copy (#4071), for 7 days
   * after it did.
   */
  readyMadeUpdatedAt?: WireDate;
  /**
   * An edited copy of a ready-made workflow whose ready-made version changed since the daemon made
   * the copy (#4071): what the newer version changes. The daemon never writes over an edited copy.
   */
  newerReadyMade?: string;
  awaitingApproval?: WorkflowApproval;
  deniedHere?: WorkflowApproval;
  lastFiredAt?: WireDate;
  lastFiredBy?: WorkflowCause;
  cooldownEndsAt?: WireDate;
  /**
   * When a fire held outside the workflow's hours: can start (#4818): the first time its hours: are
   * open once its cooldown is over. Absent while its hours: are open by then.
   */
  hoursOpenAt?: WireDate;
  holdsAFire: boolean;
  queued: number;
  offReason?: WorkflowOffReason;
  standingAgentID?: UUID;
  mcpTriggers?: MCPTriggerStatus[];
}

export type WorkflowTrigger = WorkflowTriggerStored;

export type WorkflowTriggerStored =
  | { schedule: { _0: WorkflowSchedule } }
  | { unrecognised: { name: string; keys: Record<string, JSONValue> } };

export type WorkflowWhenDone =
  | "keep"
  | "archive-allowed"
  | "archive";

export interface WorkflowWriteRequest {
  workflowID: string;
  content: string;
}

export interface WorkflowsListRequest {
  folder?: URLString;
  scope?: "folder" | "user";
}

export type WorktreeChoice =
  | { new: Record<string, never> }
  | { existing: { _0: URLString } }
  | { named: { _0: string } }
  | { branch: { _0: string } };

export interface WorktreeRemovalRequest {
  root: URLString;
  confirmed: boolean;
  folder: URLString;
}

export interface WorktreeRemoved {
  removedBranch: boolean;
}

export interface WorktreeSize {
  bytes: number;
  partial: boolean;
}

export interface WorktreeSizeNote {
  root: URLString;
  size: WorktreeSize;
}

export interface WorktreeStatus {
  uncommitted: number;
  ahead?: number;
  behind?: number;
  unmerged?: number;
}

export interface WorktreeSummary {
  name: string;
  root: URLString;
  branch?: string;
  exists: boolean;
  madeByApp: boolean;
  agents: UUID[];
  status?: WorktreeStatus;
  size?: WorktreeSize;
  isFolder: boolean;
}

export interface WorktreesListRequest {
  folder: URLString;
}

export interface WorktreesListResponse {
  isRepository: boolean;
  canMakeNew: boolean;
  whyNot?: string;
  worktrees: WorktreeSummary[];
  branches: BranchSummary[];
}

export interface WorktreesSized {
  sizes: WorktreeSizeNote[];
}

export interface WriteFailure {
  cause: WriteFailureCause;
  path?: string;
  what: string;
  message: string;
}

export type WriteFailureCause =
  | "diskFull"
  | "notAllowed"
  | "readOnly";

/**
 * Your layer (#2957, data-model.md "YourPolicy"): the rules, kept on the keeper and sent, signed,
 * to your other machines. No agent, MCP tool or workflow can change it (FR-010).
 */
export interface YourPolicy {
  rules: PolicyRules;
  /** One higher at each save. A machine refuses a lower one (FR-011). */
  revision: number;
  changed: WireDate;
  /** Which client saved it. */
  changedFrom?: { client: string; kind: "mac" | "remote" | "web" };
  /** The person's id (the user scope's user, or local for a person with no control plane). */
  person: string;
  /** The host id of the keeper (research R4). */
  keeper: string;
}

/**
 * policy/yours (#2957): your layer, which machine is the keeper, and the person key this machine
 * has pinned.
 */
export interface YourPolicyState {
  policy: YourPolicy;
  keeper: PolicyKeeper;
  pinnedKeyID?: string;
  /**
   * The signed copy, when this machine keeps one (#2957): the Mac window passes it to a server over
   * its direct link with policy/applyYours (research R3, path 2).
   */
  signed?: SignedYourPolicy;
  /**
   * Your rules from a copy of your layer this machine cannot trust (#3230): the newest such copy.
   * Its rules do not apply until the person signs them again here.
   */
  untrusted?: UntrustedYourPolicy;
}

